// Independent in-memory design preview. No host writes or external services.
let editorTab='content',editorOrigin=null,editorSequence=[],pendingNav=null,tagReturn='entries',tagKind='prefix',settingQuery='',listPage=0,expanded=new Set(),sheet=null,fullEditor=false,keywordText={key:false,keysecondary:false};
let tags={prefix:['[世界]','[规则]','[人物]','[剧情]'],suffix:['【常用】','【待补】']};
let globalSettings={world_info_depth:2,world_info_budget:25,world_info_budget_cap:0,world_info_min_activations:0,world_info_min_activations_depth_max:0,world_info_max_recursion_steps:0,world_info_character_strategy:0,world_info_include_names:false,world_info_recursive:true,world_info_case_sensitive:false,world_info_match_whole_words:false,world_info_use_group_scoring:false,world_info_overflow_alert:true,pin:false};
let bindings={primary:'b2',extra:[],chat:'',persona:''};
const dragDots='<svg viewBox="0 0 16 20" fill="currentColor" aria-hidden="true"><circle cx="5" cy="5" r="1.3"/><circle cx="11" cy="5" r="1.3"/><circle cx="5" cy="10" r="1.3"/><circle cx="11" cy="10" r="1.3"/><circle cx="5" cy="15" r="1.3"/><circle cx="11" cy="15" r="1.3"/></svg>';
const native=(...keys)=>`data-native="${keys.join(' ')}"`;
const WI=(...nums)=>native(...nums.map(n=>'WorldInfo:'+n)),ET=(...nums)=>native(...nums.map(n=>'entry_edit_template:'+n));
const fieldNative={key:[0,1,2],keysecondary:[4,5,6],selectiveLogic:[3],outletName:[7],scanDepth:[8],caseSensitive:[9],matchWholeWords:[10],useGroupScoring:[11],automationId:[12],delayUntilRecursion:[13,17],excludeRecursion:[15],preventRecursion:[16],ignoreBudget:[18],content:[19],groupOverride:[20],group:[21],groupWeight:[22],sticky:[23],cooldown:[24],delay:[25],characterFilterExclude:[26],characterFilterNames:[27],characterFilterTags:[27],triggers:[29],selective:[30],useProbability:[31],addMemo:[32],matchCharacterDescription:[34],matchCharacterPersonality:[35],matchScenario:[36],matchPersonaDescription:[37],matchCharacterDepthPrompt:[38],matchCreatorNotes:[39],disable:[42],comment:[43],constant:[44],vectorized:[44],position:[45],depth:[46],order:[47],probability:[48]};
const fieldTab={key:'activation',keysecondary:'activation',selectiveLogic:'activation',constant:'activation',vectorized:'activation',probability:'activation',comment:'content',content:'content',disable:'content',position:'injection',depth:'injection',role:'injection',outletName:'injection',order:'injection'};
const tabNames={content:'内容',activation:'激活',injection:'注入',advanced:'高级'};
const tabFor=k=>fieldTab[k]||'advanced';
const help={order:'原生扫描优先级；最终注入顺序需要宿主装配层一起核对。',depth:'0 表示最靠近当前消息。',outletName:'通过出口宏引用，不会因填写名称而自动注入。',scanDepth:'留空沿用全局；0 是明确数值。',sticky:'激活后持续的消息数；留空表示未设置。',cooldown:'激活后暂不再激活的消息数。',delay:'到达指定消息数后才允许激活。',group:'同组条目参与互斥选择；与标题前后缀标签独立。',groupWeight:'组内随机选取权重。',automationId:'与自动化联动的原生标识，重命名不会改动。',selective:'原生兼容字段，保留原值；不自动重置旧条目。',useProbability:'保留原生兼容开关；关闭时不应把概率显示当成实际抽签。',addMemo:'原生兼容字段，仅按用户修改保存。',characterFilterNames:'每行一项，保留名称中的逗号。',characterFilterTags:'角色分类标签，与名称前后缀标签互不替代。'};
// Seed records use arrays and native defaults, with visible sample mode mirrored to native flags.
entries.forEach(e=>{if(typeof e.key==='string')e.key=e.key?e.key.split(','):[];if(typeof e.keysecondary==='string')e.keysecondary=e.keysecondary?e.keysecondary.split(','):[];e.constant=e.mode==='constant';e.vectorized=e.mode==='vector';e.selective=true;e.groupWeight=100;});
function snapshot(){return JSON.stringify({books,entries,tags,globalSettings,bindings,auto})}
remember=function(){history.push(snapshot());if(history.length>30)history.shift();dirty=true;plan=null};
undo=function(){if(!history.length)return;const s=JSON.parse(history.pop());books=s.books;entries=s.entries;tags=s.tags||tags;globalSettings=s.globalSettings||globalSettings;bindings=s.bindings||bindings;auto=s.auto??auto;plan=null;selected=new Set([...selected].filter(id=>entries.some(e=>e.uid===id)));if(!books.some(b=>b.id===book))book=books[0]?.id||'';dirty=history.length>0;render();say('已撤销上一步')};
function collectTags(){for(const e of entries){const pre=e.comment.match(/^(\[[^\]\n]+\]|【[^】\n]+】)/)?.[0],suf=e.comment.match(/(\[[^\]\n]+\]|【[^】\n]+】)$/)?.[0];if(pre&&!tags.prefix.includes(pre))tags.prefix.push(pre);if(suf&&suf!==pre&&!tags.suffix.includes(suf))tags.suffix.push(suf)}}
function titleGroup(n){return tags.prefix.filter(t=>n.startsWith(t)).sort((a,b)=>b.length-a.length)[0]||(n.match(/^(\[[^\]]+\]|【[^】]+】)/)||['未分组'])[0]}
function groupRank(g){const i=tags.prefix.indexOf(g);return i<0?tags.prefix.length:i}
groupSort=function(){remember();collectTags();const own=entries.filter(e=>e.book===book).sort((a,b)=>groupRank(titleGroup(a.comment))-groupRank(titleGroup(b.comment)));let i=0;entries=entries.map(e=>e.book===book?own[i++]:e);displaySort='custom';listPage=0;render();say('已按标签顺序归组，组内手动顺序保留')};
autogroup=function(id){if(!auto)return;collectTags();const e=entries.find(e=>e.uid===id);if(!e)return;const rest=entries.filter(e=>e.uid!==id),g=titleGroup(e.comment),indices=rest.map((x,i)=>x.book===e.book&&titleGroup(x.comment)===g?i:-1).filter(i=>i>=0);let at=indices.length?indices.at(-1)+1:rest.findIndex(x=>x.book===e.book&&groupRank(titleGroup(x.comment))>groupRank(g));if(at<0){const end=rest.map((x,i)=>x.book===e.book?i:-1).filter(i=>i>=0).at(-1);at=end===undefined?rest.length:end+1}rest.splice(at,0,e);entries=rest};
shown=function(){let a=entries.filter(e=>e.book===book&&(!query||(e.comment+'\n'+e.content+'\n'+(e.key||[]).join(' ')).toLowerCase().includes(query.toLowerCase())));const n=k=>(x,y)=>(Number(x[k])||0)-(Number(y[k])||0),lex=(x,y)=>String(x.comment).localeCompare(String(y.comment),'zh');const sorts={title:lex,titleDesc:(a,b)=>lex(b,a),length:(a,b)=>a.content.length-b.content.length,lengthDesc:(a,b)=>b.content.length-a.content.length,depth:n('depth'),depthDesc:(a,b)=>n('depth')(b,a),order:n('order'),orderDesc:(a,b)=>n('order')(b,a),uid:(a,b)=>String(a.uid).localeCompare(String(b.uid),undefined,{numeric:true}),uidDesc:(a,b)=>String(b.uid).localeCompare(String(a.uid),undefined,{numeric:true}),probabilityAsc:n('probability'),probability:(a,b)=>n('probability')(b,a),priority:(a,b)=>Number(a.disable)-Number(b.disable)||Number(b.mode==='constant')-Number(a.mode==='constant')||n('order')(b,a),search:(a,b)=>Number(b.comment.includes(query))-Number(a.comment.includes(query))};if(sorts[displaySort])a.sort(sorts[displaySort]);return a};
function syncDraft(){if(!draft)return;const n=$('#entry-name'),c=$('#entry-content');if(n)draft.comment=n.value;if(c)draft.content=c.value;const expandedContent=$('#full-content');if(fullEditor&&expandedContent)draft.content=expandedContent.value;}
function draftChanged(){syncDraft();return JSON.stringify(draft)!==editorOrigin}
function captureEditorSequence(){editorSequence=shown().map(e=>e.uid)}
edit=function(id){captureEditorSequence();editing=id;draft=structuredClone(entries.find(e=>e.uid===id));editorOrigin=JSON.stringify(draft);editorTab='content';pendingNav=null;view='editor';render();window.scrollTo(0,0)};
newEntry=function(){captureEditorSequence();editing='e'+Date.now();draft={...Object.fromEntries(catalog.fields.map(f=>[f.key,f.type==='array'?[]:f.type==='boolean'?false:f.type.endsWith('?')?null:f.type==='number'?0:''])),uid:editing,book,comment:'[世界] 新条目',content:'',mode:'keyword',probability:100,useProbability:true,selective:true,disable:false,position:0,key:[],keysecondary:[],depth:4,role:0,order:100,groupWeight:100,selectiveLogic:0};editorOrigin=null;editorTab='content';pendingNav=null;view='editor';render();window.scrollTo(0,0)};
function validateDraft(){syncDraft();if(!draft.comment.trim())return '请填写条目名称';for(const f of catalog.fields.filter(f=>f.type.startsWith('number'))){const v=draft[f.key];if(v==null){if(f.type==='number')return f.label+'不能为空';continue}if(!Number.isFinite(v)||!Number.isInteger(v)||v<0)return f.label+'必须是非负整数';if(f.key==='probability'&&v>100)return '概率必须在 0–100 之间'}return ''}
function commitDraft(){const error=validateDraft();if(error){say(error);return false}const prior=entries.find(e=>e.uid===editing),regroup=!prior||titleGroup(prior.comment)!==titleGroup(draft.comment)||prior.book!==draft.book;remember();draft.comment=draft.comment.trim();draft.constant=draft.mode==='constant';draft.vectorized=draft.mode==='vector';const saved=structuredClone(draft);if(prior)entries[entries.indexOf(prior)]=saved;else entries.push(saved);collectTags();if(regroup)autogroup(editing);editorOrigin=JSON.stringify(draft);return true}
saveEntry=function(){if(!commitDraft())return;draft=null;editing=null;pendingNav=null;view='entries';render();say('条目已保存在当前样稿中')};
function performNav(target){pendingNav=null;if(target.id){const e=entries.find(e=>e.uid===target.id);if(!e){say('该条目已不存在');return}editing=e.uid;draft=structuredClone(e);editorOrigin=JSON.stringify(draft);view='editor';render();window.scrollTo(0,0)}else{draft=null;editing=null;view=target.view||'entries';plan=null;render();window.scrollTo(0,0)}}
function requestNav(target){syncDraft();if(draft&&draftChanged()){pendingNav=target;render();$('#nav-guard')?.scrollIntoView({block:'nearest',behavior:'instant'});return}performNav(target)}
function resolveNav(action){const t=pendingNav;if(action==='cancel'){pendingNav=null;render();return}if(action==='save'&&!commitDraft())return;performNav(t)}
function stepEntry(d){if(pendingNav)return;const i=editorSequence.indexOf(editing);const id=editorSequence[i+d];if(i<0||!id){say(d<0?'已经是第一条':'已经是最后一条');return}requestNav({id})}
switchPage=function(v){if(view==='editor'){requestNav({view:v});return}if(view==='tags'&&draft&&v!=='tags'){view='editor';requestNav({view:v});return}view=v;plan=null;menu=null;render();window.scrollTo(0,0)};
function switchEditorTab(t){syncDraft();editorTab=t;settingQuery='';render();window.scrollTo(0,0)}
move=function(id,d){const e=entries.find(x=>x.uid===id),own=entries.filter(x=>x.book===e.book),index=own.indexOf(e),other=own[index+d];if(!other)return;syncDraft();remember();const a=entries.indexOf(e),b=entries.indexOf(other);[entries[a],entries[b]]=[entries[b],entries[a]];displaySort='custom';editorSequence=entries.filter(x=>x.book===book).map(x=>x.uid);render();say('已'+(d<0?'上移':'下移')+'；保留你的手动顺序')};
function reorderEntry(id,target){if(id===target)return;const e=entries.find(e=>e.uid===id),t=entries.find(e=>e.uid===target);if(!e||!t||e.book!==t.book)return;remember();const a=entries.indexOf(e),b=entries.indexOf(t);entries.splice(a,1);entries.splice(b,0,e);displaySort='custom';render();say('已调整条目顺序')}
function capsuleHTML(kind,i,apply=true){const t=tags[kind][i];return `<span class="capsule ${kind==='suffix'?'suffix':''}"><button aria-label="${apply?'插入':'选择'}${kind==='prefix'?'前缀':'后缀'} ${esc(t)}" onclick="${apply?`applyTag('${kind}',${i})`:`copyTag('${kind}',${i})`}">${esc(t)}</button><button class="copy" aria-label="复制标签 ${esc(t)}" onclick="copyTag('${kind}',${i})"><svg viewBox="0 0 20 20" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><rect x="7" y="3" width="10" height="11" rx="2"/><path d="M13 15v2H3V7h2"/></svg></button></span>`}
function suggestionsHTML(){collectTags();return ['prefix','suffix'].map(k=>`<div class="tag-caption"><span>${k==='prefix'?'常用前缀':'常用后缀'}</span>${k==='prefix'?'<button class="text-button" onclick="openTags()">管理与排序 ›</button>':'<small>点文字插入 · ⧉ 复制</small>'}</div><div class="capsules">${tags[k].slice(0,k==='prefix'?6:4).map((_,i)=>capsuleHTML(k,i)).join('')||'<span class="empty">暂无标签，可在管理中新增</span>'}${tags[k].length>(k==='prefix'?6:4)?`<button class="chip-more" onclick="tagKind='${k}';openTags()">全部 ${tags[k].length} 个 ›</button>`:''}</div>`).join('')}
function applyTag(kind,i){syncDraft();if(!draft)return;const t=tags[kind][i];if(kind==='prefix'){const old=titleGroup(draft.comment);draft.comment=(old!=='未分组'?draft.comment.slice(old.length):draft.comment).trimStart();draft.comment=t+' '+draft.comment;}else{const old=tags.suffix.filter(x=>draft.comment.endsWith(x)).sort((a,b)=>b.length-a.length)[0];draft.comment=(old?draft.comment.slice(0,-old.length):draft.comment).trimEnd()+' '+t;}$('#entry-name').value=draft.comment;$('#title-status').textContent='标签已插入，保存条目后生效';}
async function copyTag(kind,i){const t=tags[kind][i];try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(t);say('已复制 '+t)}catch(e){sheet={type:'copy',text:t};renderSheet()}}
function openTags(){syncDraft();tagReturn=view;view='tags';render();window.scrollTo(0,0)}
function filterTags(value){document.querySelectorAll('.tag-row').forEach(el=>{el.classList.toggle('hidden',!tags[el.dataset.tagKind][Number(el.dataset.tagIndex)].toLowerCase().includes(value.toLowerCase()))})}
function closeTags(){view=tagReturn;render()}
function moveTag(kind,i,d){if(i+d<0||i+d>=tags[kind].length)return;remember();[tags[kind][i],tags[kind][i+d]]=[tags[kind][i+d],tags[kind][i]];render();say('标签顺序已更新；已有条目顺序保持')}
function addTag(){const v=$('#new-tag').value.trim();if(!v){say('请输入标签文字');return}if(tags[tagKind].includes(v)){say('该标签已经存在');return}remember();tags[tagKind].push(v);render();say('标签已加入建议库')}
function tagsPage(){collectTags();return `<div class="page-intro"><div><div class="eyebrow">NAME LABELS</div><h2>前后缀标签</h2><p class="hint">排成你习惯的顺序。调整标签库不会改写现有标题。</p></div><button class="ghost" onclick="closeTags()">返回</button></div><div class="panel"><div class="editor-tabs" style="grid-template-columns:1fr 1fr;position:static"><button class="${tagKind==='prefix'?'active':''}" onclick="tagKind='prefix';render()">前缀</button><button class="${tagKind==='suffix'?'active':''}" onclick="tagKind='suffix';render()">后缀</button></div><input class="tag-search" aria-label="搜索标签" placeholder="搜索已有标签" oninput="filterTags(this.value)"><div class="tags-list">${tags[tagKind].map((t,i)=>`<div class="tag-row" data-tag-kind="${tagKind}" data-tag-index="${i}"><button class="drag-handle icon ghost" aria-label="拖动标签 ${esc(t)}" data-drag-tag="${i}" data-kind="${tagKind}">${dragDots}</button>${capsuleHTML(tagKind,i,false)}<button class="icon ghost" aria-label="上移标签 ${esc(t)}" ${i===0?'disabled':''} onclick="moveTag('${tagKind}',${i},-1)">↑</button><button class="icon ghost" aria-label="下移标签 ${esc(t)}" ${i===tags[tagKind].length-1?'disabled':''} onclick="moveTag('${tagKind}',${i},1)">↓</button></div>`).join('')}</div><div class="divider"></div><label class="field"><span>新增${tagKind==='prefix'?'前缀':'后缀'}</span><input id="new-tag" placeholder="例如：${tagKind==='prefix'?'[地点]':'【待完善】'}" onkeydown="if(event.key==='Enter')addTag()"></label><button class="primary" onclick="addTag()">加入标签库</button><p class="hint">拖住左侧圆点排序，或使用上下箭头。点胶囊可复制；在标题下点文字可插入。自动归组沿用前缀库顺序。</p></div>`}
function fieldHelp(key){return help[key]?`<p class="field-help">${help[key]}</p>`:''}
function keywordEditor(key,label){const a=Array.isArray(draft[key])?draft[key]:[String(draft[key]||'')];return `<div class="field wide" data-field-wrap="${key}" ${ET(...fieldNative[key])}><span>${label}</span><div class="keyword-mode"><small>正则可用 /表达式/标志；每项独立保留</small><button class="text-button" onclick="syncDraft();keywordText['${key}']=!keywordText['${key}'];render()">${keywordText[key]?'切换标签输入':'切换纯文本'}</button></div>${keywordText[key]?`<textarea data-field="${key}" style="min-height:110px" placeholder="每行一个关键词或正则" oninput="draft['${key}']=this.value.split('\n').filter(x=>x!=='')">${esc(a.join('\n'))}</textarea>`:`${(a.length?a:['']).map((v,i)=>`<div class="keyword-row"><input data-field="${key}" aria-label="${label} ${i+1}" value="${esc(v)}" oninput="draft['${key}'][${i}]=this.value"><button class="icon ghost" aria-label="删除${label} ${i+1}" onclick="syncDraft();draft['${key}'].splice(${i},1);render()">×</button></div>`).join('')}<button class="text-button" onclick="syncDraft();draft['${key}'].push('');render()">＋ 添加关键词</button>`}</div>`}
fieldHTML=function(f){const key=f.key,v=draft[key],attrs=`data-field="${key}"`,wrap=`data-field-wrap="${key}" ${ET(...(fieldNative[key]||[]))}`;let control='';if(['key','keysecondary'].includes(key))return keywordEditor(key,f.label);if(key==='triggers'){const opts=catalog.controls.find(c=>c.id==='triggers').options;return `<div class="field wide" ${wrap}><span>适用生成类型</span><div class="trigger-grid">${opts.map(o=>`<label class="checkfield"><input ${attrs} type="checkbox" value="${o.value}" ${(v||[]).includes(o.value)?'checked':''} onchange="draft.triggers=this.checked?[...new Set([...draft.triggers,this.value])]:draft.triggers.filter(x=>x!==this.value)">${o.label}</label>`).join('')}</div><p class="field-help">不选表示不限生成类型。</p></div>`}if(key==='delayUntilRecursion')return `<div class="field" ${wrap}><label class="checkfield"><input type="checkbox" ${v>0?'checked':''} onchange="syncDraft();draft.delayUntilRecursion=this.checked?1:0;render()">延迟到递归激活</label><label class="field" style="margin-top:8px"><span>递归等级</span><input ${attrs} type="number" min="1" ${!v?'disabled':''} value="${v||1}" oninput="draft.delayUntilRecursion=this.value===''?null:Number(this.value)"></label></div>`;if(fieldOptions[key])control=`<select ${attrs} onchange="syncDraft();draft['${key}']=Number(this.value);${key==='position'?'render()':''}">${fieldOptions[key].map(([n,t])=>`<option value="${n}" ${String(v??0)===n?'selected':''}>${t}</option>`).join('')}</select>`;else if(f.type==='boolean')return `<div data-field-wrap="${key}" ${ET(...(fieldNative[key]||[]))}><label class="checkfield"><input ${attrs} type="checkbox" ${v?'checked':''} onchange="draft['${key}']=this.checked">${f.label}</label>${fieldHelp(key)}</div>`;else if(f.type==='boolean?')control=`<select ${attrs} onchange="draft['${key}']=this.value==='null'?null:this.value==='true'"><option value="null" ${v==null?'selected':''}>沿用全局</option><option value="true" ${v===true?'selected':''}>是</option><option value="false" ${v===false?'selected':''}>否</option></select>`;else if(f.type==='array')control=`<textarea ${attrs} style="min-height:90px" placeholder="每行一项" oninput="draft['${key}']=this.value.split('\n').filter(x=>x!=='')">${esc((v||[]).join('\n'))}</textarea>`;else control=`<input ${attrs} ${f.type.startsWith('number')?'type="number" min="0" step="1"':''} value="${esc(v??'')}" placeholder="${f.type.endsWith('?')?'留空沿用／未设置':''}" oninput="draft['${key}']=${f.type.startsWith('number')?"this.value===''?null:Number(this.value)":"this.value"}">`;return `<label class="field" ${wrap}><span>${f.label}</span>${control}${fieldHelp(key)}</label>`};
function fields(keys){return keys.map(k=>fieldHTML(catalog.fields.find(f=>f.key===k))).join('')}
function editorGuard(){return pendingNav?`<div class="guard" id="nav-guard" role="alert"><b>这条还有未保存修改</b><p class="hint">先处理当前草稿，再${pendingNav.id?'切换条目':'离开编辑页'}。</p><div class="flex"><button class="primary" onclick="resolveNav('save')">保存并继续</button><button onclick="resolveNav('discard')">放弃并继续</button><button class="ghost" onclick="resolveNav('cancel')">留在本条</button></div></div>`:''}
function editorContent(){return `<div class="panel content-pane"><div class="title-tools"><h2>名称与正文</h2><label class="checkfield" ${ET(42)}><input data-field="disable" type="checkbox" ${!draft.disable?'checked':''} onchange="draft.disable=!this.checked">启用</label></div><label class="field" style="margin-top:16px" data-field-wrap="comment" ${ET(43)}><span>条目名称</span><input id="entry-name" data-field="comment" value="${esc(draft.comment)}" oninput="draft.comment=this.value;document.querySelector('#title-status').textContent='标题修改后，保存才生效'"></label><div class="suggestions" id="title-suggestions">${suggestionsHTML()}</div><div class="hint" id="title-status" aria-live="polite" style="margin-top:8px">已有标签自动收集；前后缀可分别调整。</div><div class="divider"></div><div class="title-tools"><label for="entry-content">正文</label><button class="text-button" ${ET(14)} onclick="syncDraft();fullEditor=true;renderOverlay()">展开编辑器 ↗</button></div><textarea id="entry-content" class="main-content-area" data-field="content" ${ET(19)} oninput="draft.content=this.value;document.querySelector('#char-count').textContent=this.value.length+' 字符'">${esc(draft.content)}</textarea><div class="row hint" style="margin-top:8px"><span id="char-count">${draft.content.length} 字符</span><span>Token 计数待接宿主</span></div><div class="divider"></div><label class="checkfield"><input type="checkbox" ${auto?'checked':''} onchange="auto=this.checked">新建／更换前缀后自动归组</label><p class="field-help">普通保存保留手动位置。手动跨组移动允许，点击“按标签归组”时再统一整理。</p></div>`}
function editorActivation(){return `<div class="panel"><h2>激活方式</h2><label class="field" data-field-wrap="constant" ${ET(44)}><span>触发策略</span><select id="mode" data-field="constant" onchange="syncDraft();draft.mode=this.value;draft.constant=this.value==='constant';draft.vectorized=this.value==='vector';render()">${Object.entries(modes).map(([k,v])=>`<option value="${k}" ${draft.mode===k?'selected':''}>${k==='constant'?'常驻':'条件 · '+v}</option>`).join('')}</select></label><div data-field-wrap="vectorized" data-field="vectorized"></div>${draft.mode==='condition'?`<div class="native-state">条件接口待接入 · 暂不注入</div><label class="field"><span>条件集合引用</span><input value="${esc(draft.ruleRef||'')}" placeholder="选择或填写规则引用" oninput="draft.ruleRef=this.value"></label><p class="hint">复杂条件由条件引擎提供。通过后仍检查概率、延时、互斥和预算。</p>`:draft.mode==='vector'?'<div class="native-state">向量触发已保留 · 服务状态待接宿主</div>':draft.mode==='constant'?'<p class="hint">不依赖关键词，仍遵守启用状态、适用范围、概率、延时和预算。</p>':'<p class="hint">以关键词或正则匹配扫描文本，再应用辅助逻辑。</p>'}<div class="settings-group"><label class="field" data-field-wrap="probability" ${ET(48)}><span>激活概率 %</span><div class="setting-range"><input type="range" min="0" max="100" value="${draft.probability??100}" aria-label="激活概率滑块" oninput="draft.probability=Number(this.value);document.querySelector('#prob').value=this.value"><input id="prob" data-field="probability" type="number" min="0" max="100" value="${draft.probability??100}" oninput="draft.probability=this.value===''?null:Number(this.value)"></div></label></div></div><div class="panel"><h2>关键词与辅助逻辑</h2><p class="hint">各策略切换时保留原关键词，未使用也不清空。</p><div class="controls-grid">${fields(['key','selectiveLogic','keysecondary'])}</div></div>`}
function editorInjection(){return `<div class="panel"><h2>注入位置</h2><p class="hint">选择条目放入提示词的位置；指定深度时再设置消息角色。</p><div class="controls-grid">${fields(['position'])}${draft.position===4?fields(['role','depth']):draft.position===7?fields(['outletName']):''}</div><details><summary>其他位置参数 <span class="details-caption">保留未使用的值</span></summary><div class="controls-grid">${fields(['role','depth','outletName'].filter(k=>draft.position===4?!['role','depth'].includes(k):draft.position===7?k!=='outletName':true))}</div></details></div><div class="panel"><h2>排布与优先级</h2><p class="hint">列表上移下移改变显示队列。正式版将核对同位置的扫描和最终注入顺序。</p>${fields(['order'])}<div class="editor-tools">${entryMoveButtons(editing)}</div></div>`}
function editorAdvanced(){const sections=[['扫描与递归',['scanDepth','caseSensitive','matchWholeWords','ignoreBudget','excludeRecursion','preventRecursion','delayUntilRecursion'],'沿用全局的设置保持三态，不把留空当作关闭。'],['互斥与延时',['group','groupOverride','groupWeight','useGroupScoring','sticky','cooldown','delay'],'决定同组选择及条目持续、生效和冷却时间。'],['适用范围',['characterFilterNames','characterFilterTags','characterFilterExclude','triggers'],'限定角色、角色标签和生成类型。'],['额外匹配来源',['matchCharacterDescription','matchCharacterPersonality','matchScenario','matchPersonaDescription','matchCharacterDepthPrompt','matchCreatorNotes'],'选择聊天正文之外参与扫描的内容。'],['自动化联动',['automationId'],'保留原生自动化标识。'],['兼容设置',['selective','useProbability','addMemo'],'旧条目字段保持原值，不因换界面自动重置。']];return `<div class="panel"><h2>高级设置</h2>${sections.map(([name,ks,desc],i)=>`<details class="advanced-section" data-section="${name}" ${i===0?'open':''} ${ET(i===3?33:41)}><summary>${name}<span class="details-caption">${ks.length} 项</span></summary><div><p class="hint">${desc}</p><div class="controls-grid">${fields(ks)}</div></div></details>`).join('')}<p class="hint">UID：${esc(draft.uid)} · 原生扩展字段在正式接线时原样保留。</p></div>`}
function entryMoveButtons(id){const own=entries.filter(e=>e.book===book),idx=own.findIndex(e=>e.uid===id);return `<button ${idx<=0?'disabled':''} onclick="move('${id}',-1)">↑ 上移</button><button ${idx<0||idx===own.length-1?'disabled':''} onclick="move('${id}',1)">↓ 下移</button>`}
function editorPageV2(){const ix=editorSequence.indexOf(editing);return `<div class="editor-top swipe-surface"><button class="ghost" onclick="requestNav({view:'entries'})">‹ 返回条目</button><div class="editor-counter"><b>${ix<0?'新条目':`${ix+1} / ${editorSequence.length}`}</b>${esc(books.find(b=>b.id===draft.book)?.name||'世界书')}</div></div><div class="editor-meta swipe-surface"><span class="pill gold">${modes[draft.mode]} · ${draft.probability??100}%</span><div class="editor-tools">${entryMoveButtons(editing)}</div></div>${editorGuard()}<div class="nav-entries swipe-surface compact-nav"><button id="prev-entry" ${ix<=0?'disabled':''} onclick="stepEntry(-1)">‹ 上一条</button><button id="next-entry" ${ix<0||ix>=editorSequence.length-1?'disabled':''} onclick="stepEntry(1)">下一条 ›</button></div><div class="help-line swipe-surface">左右轻扫页面空白区域可切条 · 编辑框内保留文字操作</div><div class="editor-tabs">${Object.entries(tabNames).map(([k,t])=>`<button class="${editorTab===k?'active':''}" onclick="switchEditorTab('${k}')">${t}</button>`).join('')}</div><div class="toolbar"><input id="setting-search" placeholder="查找设置：粘性、角色、深度…" aria-label="查找条目设置" value="${esc(settingQuery)}" oninput="settingQuery=this.value;renderSettingResults()"></div><div id="setting-results"></div><div class="editor-layout"><section class="editor-form swipe-surface">${editorTab==='content'?editorContent():editorTab==='activation'?editorActivation():editorTab==='injection'?editorInjection():editorAdvanced()}</section><aside class="editor-aside panel"><div class="eyebrow">ENTRY SUMMARY</div><h3>${esc(draft.comment)}</h3><div class="divider"></div><p class="hint">${draft.disable?'条目已关闭':'条目已启用'} · ${positionText(draft)}</p><p class="hint">${modes[draft.mode]} · ${draft.probability??100}%</p><p class="hint">${draft.content.length} 字符</p><div class="divider"></div><p class="hint">修改仅保存在本次样稿。条件结果、Token和实际注入状态待接宿主。</p><button class="text-button" onclick="openTags()">管理前后缀标签 ›</button></aside></div>`}
function renderSettingResults(){const el=$('#setting-results');if(!el)return;if(!settingQuery.trim()){el.innerHTML='';return}const q=settingQuery.toLowerCase();const matches=catalog.fields.filter(f=>(f.label+' '+f.key).toLowerCase().includes(q));el.innerHTML=`<div class="panel search-results">${matches.map(f=>`<button onclick="locateField('${f.key}')">${f.label}<small>${tabNames[tabFor(f.key)]} › ${f.section}</small></button>`).join('')||'<p class="hint">没有匹配设置。</p>'}</div>`}
function locateField(k){syncDraft();editorTab=tabFor(k);settingQuery='';render();const el=document.querySelector(`[data-field-wrap="${k}"]`)||document.querySelector(`[data-field="${k}"]`);if(el){let p=el.parentElement;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}el.scrollIntoView({block:'center',behavior:'instant'});el.classList.add('field-flash');setTimeout(()=>el.classList.remove('field-flash'),1300)}}
const sortsList=[['search','搜索相关'],['priority','优先级'],['custom','我的排布'],['title','标题 A → Z'],['titleDesc','标题 Z → A'],['length','正文长度 ↑'],['lengthDesc','正文长度 ↓'],['depth','深度 ↑'],['depthDesc','深度 ↓'],['order','原生优先级 ↑'],['orderDesc','原生优先级 ↓'],['uid','UID ↑'],['uidDesc','UID ↓'],['probabilityAsc','概率 ↑'],['probability','概率 ↓']];
entryHTML=function(e){const own=entries.filter(x=>x.book===e.book),i=own.indexOf(e);return `<article class="entry ${e.disable?'off':''} ${selected.has(e.uid)?'selected':''}" data-entry-id="${e.uid}"><div class="entry-head">${batchMode?`<input type="checkbox" aria-label="选择 ${esc(e.comment)}" ${selected.has(e.uid)?'checked':''} onchange="selectOne('${e.uid}',this.checked)">`:''}<div class="grow"><button class="open-title" onclick="edit('${e.uid}')"><div class="title">${esc(e.comment)||'未命名条目'}</div></button><div class="sub"><span class="pill ${e.mode==='constant'?'gold':''}">${modes[e.mode]}</span><span class="pill gray">${e.probability??100}%</span><span class="pill gray">${positionText(e)}</span></div></div><div><button class="switch" role="switch" ${ET(42)} aria-label="启用 ${esc(e.comment)}" aria-checked="${!e.disable}" onclick="toggle('${e.uid}')"></button></div></div><div class="entry-bottom"><div class="reorder-rail"><span class="rank">${String(i+1).padStart(2,'0')}</span><button class="drag-handle" data-drag-entry="${e.uid}" ${ET(40)} aria-label="拖动 ${esc(e.comment)}">${dragDots}</button><button aria-label="上移 ${esc(e.comment)}" ${i===0?'disabled':''} onclick="move('${e.uid}',-1)">↑</button><button aria-label="下移 ${esc(e.comment)}" ${i===own.length-1?'disabled':''} onclick="move('${e.uid}',1)">↓</button></div><div class="quick-tools"><button ${ET(41)} aria-label="展开正文 ${esc(e.comment)}" aria-expanded="${expandAll||expanded.has(e.uid)}" onclick="expanded.has('${e.uid}')?expanded.delete('${e.uid}'):expanded.add('${e.uid}');render()">${expandAll||expanded.has(e.uid)?'收起':'正文'}</button><button aria-label="${esc(e.comment)} 操作" onclick="menu=menu==='${e.uid}'?null:'${e.uid}';render()">更多 ⋯</button></div></div>${expandAll||expanded.has(e.uid)?`<div class="entry-summary">${esc(e.content)}</div><p class="hint">UID ${esc(e.uid)} · ${e.content.length} 字符 · Token 待接</p>`:''}${menu===e.uid?`<div class="entry-actions"><button onclick="edit('${e.uid}')">编辑</button><button ${ET(50)} onclick="duplicate('${e.uid}')">复制</button><button ${ET(49)} onclick="sheet={type:'transfer',id:'${e.uid}'};renderSheet()">移动／复制到书</button><button class="danger" ${ET(51)} onclick="sheet={type:'deleteEntry',id:'${e.uid}'};renderSheet()">删除</button></div>`:''}</article>`};
function entriesPageV2(){const all=shown(),pages=Math.max(1,Math.ceil(all.length/pageSize));listPage=Math.min(listPage,pages-1);return `<div class="page-intro"><div><div class="eyebrow">LOREBOOK WORKSPACE</div><h2>条目工作区</h2><p class="hint">随手编辑，按你的顺序排列。</p></div><div class="count-line"><strong>${all.length}</strong>条目</div></div><div class="toolbar"><select class="list-book-select" aria-label="当前世界书" ${WI(24)} onchange="book=this.value;query='';listPage=0;render()">${books.map(b=>`<option value="${b.id}" ${b.id===book?'selected':''}>${esc(b.name)}</option>`).join('')}</select><button class="primary" ${WI(30)} ${!book?'disabled':''} onclick="newEntry()">＋ 新增</button></div><div class="toolbar"><input ${WI(35)} aria-label="搜索条目" placeholder="搜索名称、正文、关键词" value="${esc(query)}" oninput="query=this.value;listPage=0;renderEntriesOnly()"><button onclick="batchMode=!batchMode;render()">${batchMode?'完成多选':'多选'}</button><button onclick="openTags()">标签</button></div><div class="toolbar"><select aria-label="浏览排序" ${WI(36)} onchange="displaySort=this.value;listPage=0;render()">${sortsList.map(([k,t])=>`<option value="${k}" ${displaySort===k?'selected':''}>${t}</option>`).join('')}</select></div><details class="panel"><summary>整理工具 <span class="details-caption">排序、回填与显示</span></summary><div class="list-tools"><button onclick="groupSort()">按标签归组</button><button ${WI(31)} onclick="expandAll=true;render()">展开全部正文</button><button ${WI(32)} onclick="expandAll=false;expanded.clear();render()">收起全部正文</button><button ${WI(33)} onclick="utilityPreview('backfill')">关键词回填空标题</button><button ${WI(34)} onclick="utilityPreview('order')">当前排序写入 Order</button><button ${WI(37)} onclick="render();say('已刷新当前样稿数据')">刷新列表</button></div><p class="field-help">长度排序按字符长度，不是精确 Token。浏览排序不会自动覆盖手动排布。</p></details>${batchMode?`<div class="toolbar"><button onclick="shown().forEach(e=>selected.add(e.uid));render()">选择全部结果</button><button onclick="selected.clear();render()">清空</button><small>已选 ${selected.size} 条</small></div>`:''}<div id="entry-list">${all.slice(listPage*pageSize,(listPage+1)*pageSize).map(entryHTML).join('')||'<div class="empty-state">没有匹配条目</div>'}</div><div id="pagination">${pagerHTML(all.length)}</div><p class="help-line">拖动圆点或使用 ↑ ↓ 调整排布。实际提示词顺序及注入状态待接宿主。</p>`}
function pagerHTML(n){const pages=Math.max(1,Math.ceil(n/pageSize));return `<div class="pager"><button ${listPage===0?'disabled':''} onclick="listPage--;render()">‹</button><small>${listPage+1} / ${pages}</small><button ${listPage>=pages-1?'disabled':''} onclick="listPage++;render()">›</button><select aria-label="每页条目数" onchange="pageSize=Number(this.value);listPage=0;render()">${[5,10,20,50,100].map(n=>`<option ${n===pageSize?'selected':''} value="${n}">${n} 条/页</option>`).join('')}</select></div>`}
renderEntriesOnly=function(){const a=shown();$('#entry-list').innerHTML=a.slice(listPage*pageSize,(listPage+1)*pageSize).map(entryHTML).join('')||'<div class="empty-state">没有匹配条目</div>';$('#pagination').innerHTML=pagerHTML(a.length)};
function bookOptions(current,empty=true){return (empty?'<option value="">未绑定</option>':'')+books.map(b=>`<option value="${b.id}" ${b.id===current?'selected':''}>${esc(b.name)}</option>`).join('')}
function booksPageV2(){return `<div class="page-intro"><div><div class="eyebrow">COLLECTIONS</div><h2>世界书队列</h2><p class="hint">全局与角色并列排布，来源始终清楚。</p></div><strong style="color:var(--gold);font-weight:400">${books.length} 本</strong></div><div class="shortcut-row"><button class="primary" ${WI(23)} onclick="sheet={type:'newBook'};renderSheet()">＋ 新建世界书</button><button ${WI(25)} onclick="sheet={type:'import'};renderSheet()">导入</button><label class="checkfield" ${WI(0)}><input type="checkbox" ${globalSettings.pin?'checked':''} onchange="remember();globalSettings.pin=this.checked">固定面板</label></div>${books.map((b,i)=>`<article class="entry book-card" data-book-id="${b.id}"><div class="row"><span class="book-rank">${String(i+1).padStart(2,'0')}</span><button class="grow open-title" onclick="book='${b.id}';view='entries';query='';listPage=0;render()"><div class="title">${esc(b.name)}</div><div class="sub"><span class="pill">${b.scope}</span><small>${entries.filter(e=>e.book===b.id).length} 条</small></div></button><button class="switch" ${WI(1)} role="switch" aria-label="启用世界书 ${esc(b.name)}" aria-checked="${b.enabled}" onclick="remember();books.find(b=>b.id==='${b.id}').enabled=!books.find(b=>b.id==='${b.id}').enabled;render()"></button></div><div class="book-actions"><button ${i===0?'disabled':''} onclick="moveBook(${i},-1)">↑ 上移</button><button ${i===books.length-1?'disabled':''} onclick="moveBook(${i},1)">↓ 下移</button><button ${WI(27)} onclick="sheet={type:'editBook',id:'${b.id}'};renderSheet()">改名／归属</button><button ${WI(28)} onclick="copyBook('${b.id}')">复制</button><button ${WI(26)} onclick="exportBook('${b.id}')">导出</button><button ${WI(29)} class="danger" onclick="sheet={type:'deleteBook',id:'${b.id}'};renderSheet()">删除</button></div></article>`).join('')}<div class="panel bindings"><h2>角色与对话绑定</h2><p class="hint">以下为示例绑定；正式版读取当前角色、聊天和用户人格。</p><div class="binding-row" ${native('extra:0','extra:1','extra:2')}><label for="primary-binding">角色主世界书</label><select id="primary-binding" onchange="remember();bindings.primary=this.value;render()">${bookOptions(bindings.primary)}</select></div><button class="text-button" ${!bindings.primary?'disabled':''} onclick="book=bindings.primary;view='entries';render()">打开角色主书 ›</button><details ${native('extra:3')}><summary>角色附加世界书 <span class="details-caption">${bindings.extra.length} 本</span></summary><div>${books.map(b=>`<label class="checkfield"><input type="checkbox" ${bindings.extra.includes(b.id)?'checked':''} onchange="remember();bindings.extra=this.checked?[...bindings.extra,'${b.id}']:bindings.extra.filter(x=>x!=='${b.id}')">${esc(b.name)}</label>`).join('')}</div></details>${[['chat','当前聊天'],['persona','用户人格']].map(([k,t])=>`<div class="binding-row"><label for="binding-${k}">${t}</label><select id="binding-${k}" onchange="remember();bindings['${k}']=this.value">${bookOptions(bindings[k])}</select></div>`).join('')}<p class="field-help">书籍排布不会将聊天或用户人格资料扩大为全局可见。</p></div>`}
function moveBook(i,d){if(!books[i+d])return;remember();[books[i],books[i+d]]=[books[i+d],books[i]];render()}
function copyBook(id){remember();const src=books.find(b=>b.id===id),newId='b'+Date.now();books.push({...src,id:newId,name:src.name+' 副本'});entries.filter(e=>e.book===id).forEach((e,i)=>entries.push({...structuredClone(e),uid:newId+'e'+i,book:newId}));render();say('已复制世界书及其条目，可撤销')}
function exportBook(id){const b=books.find(b=>b.id===id);const payload={format:'tisya-worldbook-preview/2',book:b,entries:entries.filter(e=>e.book===id)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='世界书样稿-'+b.name.replace(/[\\/:*?"<>|]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);say('已导出样稿 JSON；正式宿主格式待接')}
async function importPreview(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('样稿导入上限 5 MB');const x=JSON.parse(await file.text());if(x.format!=='tisya-worldbook-preview/2'||!x.book||typeof x.book.name!=='string'||!Array.isArray(x.entries))throw Error('请选择本样稿导出的 JSON；原生格式需宿主适配');if(x.entries.length>2000)throw Error('样稿最多导入 2000 条');for(const e of x.entries){if(typeof e.comment!=='string'||typeof e.content!=='string'||!modes[e.mode]||!Array.isArray(e.key)||!Array.isArray(e.keysecondary))throw Error('条目结构不完整，未导入')}remember();const id='b'+Date.now();books.push({id,name:x.book.name,scope:['全局','角色'].includes(x.book.scope)?x.book.scope:'全局',enabled:false});x.entries.forEach((e,i)=>entries.push({...structuredClone(e),uid:id+'e'+i,book:id}));collectTags();sheet=null;render();say('已导入样稿世界书，默认未启用，可撤销')}catch(e){$('#import-error').textContent=e.message}}
function utilityPreview(type){const own=type==='order'?shown():entries.filter(e=>e.book===book);const rows=own.map((e,i)=>({uid:e.uid,name:e.comment,before:type==='order'?e.order:e.comment,after:type==='order'?own.length-i:(e.comment.trim()?e.comment:(e.key||[]).find(k=>k.trim())||'')})).filter(r=>r.before!==r.after);sheet={type:'utility',operation:type,rows,snapshot:JSON.stringify(entries)};renderSheet()}
function applyUtility(){if(sheet.snapshot!==JSON.stringify(entries)){say('数据已变化，请重新预览');return}const s=sheet;remember();s.rows.forEach(r=>{entries.find(e=>e.uid===r.uid)[s.operation==='order'?'order':'comment']=r.after});sheet=null;render();say('已应用样稿修改，可撤销')}
const globalRanges=[['world_info_depth',0,1000,3,4,'扫描最近多少层聊天'],['world_info_budget',1,100,5,6,'允许世界书使用的上下文百分比'],['world_info_budget_cap',0,65536,7,8,'0 表示不设置额外上限'],['world_info_min_activations',0,100,9,10,'与最大递归次数互斥，0 表示不启用'],['world_info_min_activations_depth_max',0,100,11,12,'0 表示不限制最大扫描深度'],['world_info_max_recursion_steps',0,10,13,14,'0 不限，1 仅扫描一次；与最少激活互斥']];
function globalRange(def){const [k,min,max,a,b,h]=def;return `<label class="field" ${WI(a,b)}><span>${globalLabel(k)}</span><div class="setting-range"><input type="range" aria-label="${globalLabel(k)}滑块" data-global-range="${k}" min="${min}" max="${max}" value="${globalSettings[k]}" oninput="changeGlobal('${k}',this.value)"><input aria-label="${globalLabel(k)}数值" data-global-number="${k}" type="number" min="${min}" max="${max}" value="${globalSettings[k]}" onchange="changeGlobal('${k}',this.value)"></div><p class="field-help">${h}</p></label>`}
function changeGlobal(k,v){const spec=globalRanges.find(d=>d[0]===k),n=Number(v);if(v===''||!Number.isInteger(n)||n<spec[1]||n>spec[2]){say(`请输入 ${spec[1]}–${spec[2]} 之间的整数`);render();return}const opposite=k==='world_info_min_activations'?'world_info_max_recursion_steps':k==='world_info_max_recursion_steps'?'world_info_min_activations':null;if(opposite&&n>0&&globalSettings[opposite]>0){sheet={type:'globalConflict',key:k,value:n,other:opposite};renderSheet();return}remember();globalSettings[k]=n;document.querySelector(`[data-global-range="${k}"]`).value=n;document.querySelector(`[data-global-number="${k}"]`).value=n}
function globalPageV2(){return `<div class="page-intro"><div><div class="eyebrow">GLOBAL PREFERENCES</div><h2>全局扫描设置</h2><p class="hint">本页修改作用于示例。条目单独设置优先于“沿用全局”。</p></div></div><div class="panel"><details open ${WI(2)}><summary>扫描与预算</summary><div class="settings-grid">${globalRanges.slice(0,3).map(globalRange).join('')}</div></details><details open><summary>激活与递归限制</summary><div class="settings-grid">${globalRanges.slice(3).map(globalRange).join('')}</div></details><div class="global-section"><h3>扫描规则</h3><div class="controls-grid">${['world_info_include_names','world_info_recursive','world_info_case_sensitive','world_info_match_whole_words','world_info_use_group_scoring','world_info_overflow_alert'].map((k,i)=>`<label class="checkfield" ${WI(i+16)}><input type="checkbox" ${globalSettings[k]?'checked':''} onchange="remember();globalSettings['${k}']=this.checked">${globalLabel(k)}</label>`).join('')}</div></div><div class="global-section"><h3>原生来源优先策略</h3><select aria-label="原生角色／全局优先策略" ${WI(15)} onchange="remember();globalSettings.world_info_character_strategy=Number(this.value)">${catalog.controls.find(c=>c.id==='world_info_character_strategy').options.map(o=>`<option value="${o.value}" ${globalSettings.world_info_character_strategy==o.value?'selected':''}>${o.label}</option>`).join('')}</select><p class="field-help">正式接线将协调来源策略与可视排布，不能只调整界面顺序就宣称提示词顺序改变。</p></div></div>`}
function closeSheet(){sheet=null;renderSheet()}
function sheetContent(){const s=sheet,b=s.id?books.find(b=>b.id===s.id):null,e=s.id?entries.find(e=>e.uid===s.id):null;if(s.type==='copy')return `<h2>复制标签</h2><p class="hint">当前浏览器不允许自动写剪贴板，请长按选中文字复制。</p><input class="copy-manual" readonly value="${esc(s.text)}" onclick="this.select()"><button class="text-button" onclick="document.querySelector('.copy-manual').select()">全选文字</button>`;
if(s.type==='newBook'||s.type==='editBook')return `<h2>${b?'管理世界书':'新建世界书'}</h2><label class="field"><span>名称</span><input id="book-name" value="${esc(b?.name||'')}" placeholder="为这本世界书命名"></label><label class="field"><span>归属</span><select id="book-scope"><option ${b?.scope==='全局'?'selected':''}>全局</option><option ${b?.scope==='角色'?'selected':''}>角色</option></select></label><div class="sheet-footer"><button class="primary" onclick="saveBook()">${b?'保存':'创建'}</button></div>`;
if(s.type==='deleteBook'||s.type==='deleteEntry')return `<h2>删除${b?'世界书':'条目'}</h2><p>${esc(b?.name||e?.comment)}</p><p class="hint">${b?'同时删除本书中的 '+entries.filter(e=>e.book===b.id).length+' 条示例条目并解除示例绑定。':'删除后可以撤销。'}</p><div class="sheet-footer"><button onclick="closeSheet()">取消</button><button class="danger" onclick="confirmDelete()">确认删除</button></div>`;
if(s.type==='transfer')return `<h2>移动或复制条目</h2><p class="hint">${esc(e.comment)}</p><label class="field"><span>目标世界书</span><select id="transfer-target">${bookOptions('',false)}</select></label><label class="field"><span>处理方式</span><select id="transfer-mode"><option value="move">移动</option><option value="copy">复制，分配新 UID</option></select></label><div class="sheet-footer"><button class="primary" onclick="transferEntry()">应用到样稿</button></div>`;
if(s.type==='import')return `<h2>导入世界书</h2><p class="hint">这里可往返本样稿导出的 JSON。原生 JSON、PNG、lorebook 格式的正式导入入口保留，转换与保存待接宿主。</p><label class="field" ${WI(22)}><span>选择样稿 JSON</span><input type="file" accept=".json,application/json" onchange="importPreview(this.files[0])"></label><p id="import-error" class="error" role="alert"></p><div class="native-state">原生 JSON / PNG / lorebook：宿主适配待接，不会尝试覆盖正式数据。</div>`;
if(s.type==='utility')return `<h2>${s.operation==='order'?'当前排序写入 Order':'关键词回填空标题'}</h2><p class="hint">${s.operation==='order'?'将当前筛选结果的浏览顺序映射为递减的原生优先级；不会改变其他条目。不能据此证明实际提示词顺序。':'只处理当前书名称为空且有关键词的条目，已有名称保持。'}</p>${s.rows.map(r=>`<div class="review-row"><b>${esc(r.name)||'未命名'}</b><del>${esc(r.before)}</del><ins>${esc(r.after)}</ins></div>`).join('')||'<p class="hint">没有需要修改的条目。</p>'}<div class="sheet-footer"><button class="primary" ${!s.rows.length?'disabled':''} onclick="applyUtility()">应用 ${s.rows.length} 项</button></div>`;
if(s.type==='globalConflict')return `<h2>两项限制不能同时启用</h2><p>启用“${globalLabel(s.key)}”将把“${globalLabel(s.other)}”设为 0。</p><div class="sheet-footer"><button onclick="sheet=null;render()">保留原设置</button><button class="primary" onclick="remember();globalSettings[sheet.key]=sheet.value;globalSettings[sheet.other]=0;sheet=null;render()">确认切换</button></div>`;return ''}
function renderSheet(){let el=$('#sheet-root');if(!el){el=document.createElement('div');el.id='sheet-root';document.body.append(el)}el.innerHTML=sheet?`<div class="overlay" onclick="if(event.target===this)closeSheet()"><section class="sheet" role="dialog" aria-modal="true" aria-label="${sheet.type==='copy'?'复制标签':'世界书操作'}"><div class="row"><span class="caption">世界书操作台</span><button class="icon ghost" aria-label="关闭弹层" onclick="closeSheet()">×</button></div>${sheetContent()}</section></div>`:'';setModalState()}
function setModalState(){const modal=!!sheet||fullEditor;for(const id of ['app','nav','foot']){const el=$('#'+id);if(el)el.inert=modal}document.body.style.overflow=modal?'hidden':''}
function saveBook(){const name=$('#book-name').value.trim(),scope=$('#book-scope').value;if(!name){say('请填写世界书名称');return}remember();if(sheet.type==='newBook'){const id='b'+Date.now();books.push({id,name,scope,enabled:false});if(!book)book=id}else Object.assign(books.find(b=>b.id===sheet.id),{name,scope});sheet=null;render();say('已保存示例世界书')}
function confirmDelete(){const s=sheet;remember();if(s.type==='deleteBook'){books=books.filter(b=>b.id!==s.id);entries=entries.filter(e=>e.book!==s.id);for(const k of ['primary','chat','persona'])if(bindings[k]===s.id)bindings[k]='';bindings.extra=bindings.extra.filter(id=>id!==s.id);if(book===s.id)book=books[0]?.id||'';}else entries=entries.filter(e=>e.uid!==s.id);selected=new Set([...selected].filter(id=>entries.some(e=>e.uid===id)));sheet=null;render();say('已删除，可撤销')}
function transferEntry(){const target=$('#transfer-target').value,mode=$('#transfer-mode').value,e=entries.find(e=>e.uid===sheet.id);if(!target){say('请选择目标世界书');return}remember();let id=e.uid;if(mode==='copy'){const copy={...structuredClone(e),uid:'e'+Date.now(),book:target};entries.push(copy);id=copy.uid;}else e.book=target;autogroup(id);sheet=null;menu=null;render();say('已'+(mode==='copy'?'复制':'移动')+'到目标世界书')}
function renderOverlay(){let el=$('#fullscreen-root');if(!el){el=document.createElement('div');el.id='fullscreen-root';document.body.append(el)}el.innerHTML=fullEditor?`<div class="fullscreen-editor" role="dialog" aria-modal="true" aria-label="展开正文编辑器"><div class="row"><h2 style="margin:0">正文编辑</h2><button class="primary" onclick="draft.content=document.querySelector('#full-content').value;fullEditor=false;render()">完成</button></div><p class="hint">${esc(draft.comment)} · 完成后仍需保存条目</p><textarea id="full-content">${esc(draft.content)}</textarea></div>`:'';setModalState()}
let bulkField='position',bulkValue='0';
const bulkKeys=['position','role','depth','order','outletName','scanDepth','caseSensitive','matchWholeWords','ignoreBudget','excludeRecursion','preventRecursion','delayUntilRecursion','group','groupOverride','groupWeight','useGroupScoring','sticky','cooldown','delay','characterFilterNames','characterFilterTags','characterFilterExclude','triggers','matchCharacterDescription','matchCharacterPersonality','matchScenario','matchPersonaDescription','matchCharacterDepthPrompt','matchCreatorNotes','automationId','selective','useProbability','addMemo'];
function bulkInput(){const f=catalog.fields.find(f=>f.key===bulkField);if(fieldOptions[f.key])return `<select id="bulk-value" onchange="bulkValue=this.value;plan=null">${fieldOptions[f.key].map(([k,t])=>`<option value="${k}" ${bulkValue===k?'selected':''}>${t}</option>`).join('')}</select>`;if(f.type.startsWith('boolean'))return `<select id="bulk-value" onchange="bulkValue=this.value;plan=null">${(f.type.endsWith('?')?[['null','沿用全局']]:[]).concat([['true','是'],['false','否']]).map(([k,t])=>`<option value="${k}" ${bulkValue===k?'selected':''}>${t}</option>`).join('')}</select>`;if(f.type==='array')return `<textarea id="bulk-value" placeholder="每行一项，留空清空该字段" oninput="bulkValue=this.value;plan=null">${esc(bulkValue)}</textarea>`;return `<input id="bulk-value" ${f.type.startsWith('number')?'type="number" min="0"':''} placeholder="${f.type.endsWith('?')?'留空沿用／未设置':'字段值'}" value="${esc(bulkValue)}" oninput="bulkValue=this.value;plan=null">`}
function changeBulkField(k){bulkField=k;const f=catalog.fields.find(f=>f.key===k);bulkValue=f.type.endsWith('?')?(f.type.startsWith('boolean')?'null':''):f.type==='boolean'?'false':fieldOptions[k]?fieldOptions[k][0][0]:f.type==='number'?'0':'';plan=null;render()}
function advancedBulkPlan(){const f=catalog.fields.find(f=>f.key===bulkField);let value=bulkValue;try{if(!targets().length)throw Error('请先选择条目或修改操作范围');if(f.type.startsWith('number')){value=value===''&&f.type.endsWith('?')?null:Number(value);if(bulkValue===''&&!f.type.endsWith('?')||value!==null&&(!Number.isInteger(value)||value<0))throw Error('请输入非负整数');}else if(f.type.startsWith('boolean'))value=value==='null'?null:value==='true';else if(f.type==='array')value=value.split('\n').filter(Boolean);else if(fieldOptions[f.key])value=Number(value);if(f.key==='triggers'&&value.some(v=>!['normal','continue','impersonate','swipe','regenerate','quiet'].includes(v)))throw Error('生成类型使用 normal、continue、impersonate、swipe、regenerate、quiet，每行一个');plan={snapshot:JSON.stringify(entries),total:targets().length,field:bulkField,rows:targets().map(e=>({uid:e.uid,name:e.comment,before:e[bulkField]??'',after:value})).filter(r=>JSON.stringify(r.before)!==JSON.stringify(r.after))};$('#diffs').innerHTML=planHTML();$('#bulk-error').textContent='';$('#diffs').scrollIntoView({block:'center',behavior:'instant'});}catch(e){$('#bulk-error').textContent=e.message}}
function batchPageV2(){return `<div class="shortcut-row"><button onclick="openTags()">前后缀标签库 ›</button><button ${WI(33)} onclick="utilityPreview('backfill')">空标题回填</button><button ${WI(34)} onclick="utilityPreview('order')">浏览序写入优先级</button></div>`+batchPage()+`<div class="panel"><details><summary>更多批量字段 <span class="details-caption">注入、扫描、延时与过滤</span></summary><div><p class="hint">沿用上方操作范围（${targets().length} 条），同样先预览再应用。</p><label class="field"><span>目标字段</span><select id="bulk-field" onchange="changeBulkField(this.value)">${bulkKeys.map(k=>`<option value="${k}" ${bulkField===k?'selected':''}>${catalog.fields.find(f=>f.key===k).label}</option>`).join('')}</select></label><label class="field"><span>统一设为</span>${bulkInput()}</label><button class="primary" onclick="advancedBulkPlan()">预览该字段修改</button><p id="bulk-error" class="error" role="alert"></p></div></details></div>`}

render=function(){const tabs=[['books','世界书'],['entries','条目'],['batch','操作台'],['global','全局设置']];$('#nav').innerHTML=tabs.map(([k,v])=>`<button class="${view===k||(view==='editor'&&k==='entries')?'active':''}" onclick="switchPage('${k}')">${v}</button>`).join('');document.body.classList.toggle('editing-screen',view==='editor');$('#page-title').textContent=view==='editor'?'编辑条目':view==='tags'?'标签管理':'世界书';$('#app').innerHTML=view==='books'?booksPageV2():view==='editor'?editorPageV2():view==='batch'?batchPageV2():view==='global'?globalPageV2():view==='tags'?tagsPage():entriesPageV2();$('#foot').innerHTML=view==='editor'?`<div class="foot-inner"><button onclick="requestNav({view:'entries'})">返回列表</button><button class="primary" onclick="saveEntry()">保存条目</button></div>`:view==='tags'?`<div class="foot-inner"><button ${!history.length?'disabled':''} onclick="undo()">撤销</button><button class="primary" onclick="closeTags()">完成排序</button></div>`:`<div class="foot-inner"><button ${!history.length?'disabled':''} onclick="undo()">撤销</button>${view==='entries'?`<button class="primary" onclick="view='batch';batchScope=selected.size?'selected':'book';render()">${selected.size?'批量处理 '+selected.size+' 条':'打开操作台'}</button>`:`<button class="primary" onclick="say('当前为独立样稿，修改仅保留在本次打开期间')">示例数据</button>`}</div>`;renderSettingResults();renderSheet();renderOverlay()};
// Pointer gestures: axis-lock, input/selection exclusion, cancellation and explicit drag handles.
let gesture=null,dragState=null;
document.addEventListener('pointerdown',ev=>{if(!ev.isPrimary){gesture=null;return}if(ev.button!==0)return;const h=ev.target.closest('[data-drag-entry],[data-drag-tag]');if(h){if(h.disabled)return;const row=h.closest('[data-entry-id],[data-tag-index]');dragState={id:ev.pointerId,handle:h,row,entry:h.dataset.dragEntry,kind:h.dataset.kind,index:Number(h.dataset.dragTag),target:null,startY:ev.clientY,moved:false};h.setPointerCapture(ev.pointerId);return}if(view!=='editor'||pendingNav||sheet||fullEditor||ev.target.closest('input,textarea,select,button,a,summary,label,[contenteditable]')||String(window.getSelection()).length)return;if(!ev.target.closest('.swipe-surface'))return;gesture={id:ev.pointerId,x:ev.clientX,y:ev.clientY,blocked:false};});
document.addEventListener('pointermove',ev=>{if(dragState&&ev.pointerId===dragState.id){const d=dragState;if(Math.abs(ev.clientY-d.startY)>7)d.moved=true;if(!d.moved)return;ev.preventDefault();d.row.classList.add('drag-active');document.querySelectorAll('.drag-target').forEach(e=>e.classList.remove('drag-target'));const hit=document.elementFromPoint(ev.clientX,ev.clientY)?.closest(d.entry?'[data-entry-id]':'[data-tag-index]');if(hit&&hit!==d.row&&(!d.kind||hit.dataset.tagKind===d.kind)){hit.classList.add('drag-target');d.target=d.entry?hit.dataset.entryId:Number(hit.dataset.tagIndex)}else d.target=null;return}if(gesture&&gesture.id===ev.pointerId&&Math.abs(ev.clientY-gesture.y)>30&&Math.abs(ev.clientY-gesture.y)>Math.abs(ev.clientX-gesture.x))gesture.blocked=true;},{passive:false});
function clearDrag(){document.querySelectorAll('.drag-active,.drag-target').forEach(e=>e.classList.remove('drag-active','drag-target'));dragState=null}
document.addEventListener('pointerup',ev=>{if(dragState&&ev.pointerId===dragState.id){const d=dragState;clearDrag();if(d.moved&&d.target!==null){if(d.entry)reorderEntry(d.entry,d.target);else{remember();const t=tags[d.kind].splice(d.index,1)[0];tags[d.kind].splice(d.target,0,t);render();say('标签顺序已更新')}}return}if(!gesture||gesture.id!==ev.pointerId)return;const g=gesture;gesture=null;const dx=ev.clientX-g.x,dy=ev.clientY-g.y;if(!g.blocked&&Math.abs(dx)>=70&&Math.abs(dx)>Math.abs(dy)*1.6&&!String(window.getSelection()).length)stepEntry(dx<0?1:-1)});
document.addEventListener('pointercancel',()=>{gesture=null;clearDrag()});document.addEventListener('lostpointercapture',()=>{if(dragState)clearDrag()});window.addEventListener('blur',()=>{gesture=null;clearDrag()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&sheet){closeSheet();return}if(ev.key==='Tab'&&(sheet||fullEditor)){const root=document.querySelector(fullEditor?'.fullscreen-editor':'.sheet'),items=[...root.querySelectorAll('button,input,textarea,select,[tabindex]')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(ev.shiftKey&&(document.activeElement===first||!root.contains(document.activeElement))){last.focus();ev.preventDefault()}else if(!ev.shiftKey&&(document.activeElement===last||!root.contains(document.activeElement))){first.focus();ev.preventDefault()}}});
window.addEventListener('beforeunload',ev=>{if(dirty||(draft&&draftChanged())){ev.preventDefault();ev.returnValue=''}});
document.querySelector('header .caption').innerHTML='第二轮样稿<br>示例数据';
collectTags();render();
